var motoAtual=localStorage.getItem('motoAtual')||'m1';const SC=['moto','oleos','mans','fuels','doc','oleoIntervalo','editOleo','editMan','editFuel','kmAtual','ipva','seguro','fipe','lavagens','lavCada','editLav','fin','licHist','calib','ipvaHist','trocas','capacetes'];function K(k,id){id=id||motoAtual;return SC.includes(k)&&id!=='m1'?k+'@'+id:k}

const $=id=>document.getElementById(id), get=(k,d)=>JSON.parse(localStorage.getItem(K(k))||JSON.stringify(d)), set=(k,v)=>localStorage.setItem(K(k),JSON.stringify(v));
function today(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function fmtDate(s){if(!s)return'';let a=s.split('-');return a[2]+'/'+a[1]+'/'+a[0]}
function br(n,d=2){return Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})}
function showTab(t){['moto','man','fuel','lav','doc','gas'].forEach(x=>$(x).classList.toggle('hidden',x!==t));[['tMoto','moto'],['tMan','man'],['tFuel','fuel'],['tLav','lav'],['tDoc','doc'],['tGas','gas']].forEach(a=>$(a[0]).classList.toggle('active',a[1]===t))}
