function salvarOleo(){let km=numKm('oleoKm'),data=$('oleoData').value;if(!km||!data){alert('Informe a KM e a data.');return}let l=get('oleos',[]),i=localStorage.getItem(K('editOleo'));let intv=numKm('oleoIntervalo');if(!intv||intv<100){alert('Informe de quantos em quantos km trocar o óleo (veja o manual da moto).');return}localStorage.setItem(K('oleoIntervalo'),intv);let x={km,data,tipo:$('oleoTipo').value.trim(),intervalo:intv,prox:km+intv,valor:Number($('oleoValor').value)||0};if(i!==null){l[Number(i)]=x;localStorage.removeItem(K('editOleo'))}else l.unshift(x);set('oleos',l);limparOleo();renderOleo();alert('Troca registrada. Próxima troca: '+(km+intv).toLocaleString('pt-BR')+' km.')}
function limparOleo(){['oleoKm','oleoData','oleoTipo','oleoValor'].forEach(x=>$(x).value='');$('oleoData').value=today();$('oleoIntervalo').value=localStorage.getItem(K('oleoIntervalo'))||'';formatarKms();localStorage.removeItem(K('editOleo'));modoEdit('Oleo')}
function editarOleo(i){let x=get('oleos',[])[i];$('oleoKm').value=x.km;$('oleoData').value=x.data;$('oleoTipo').value=x.tipo||'';$('oleoValor').value=x.valor||'';$('oleoIntervalo').value=x.intervalo||(x.prox-x.km)||'';formatarKms();localStorage.setItem(K('editOleo'),i);modoEdit('Oleo','troca de óleo de '+fmtDate(x.data));showTab('moto');window.scrollTo({top:0,behavior:'smooth'})}
