function renderOleo(){let l=get('oleos',[]);if(!l.length){$('oleoResumo').innerHTML='Nenhuma troca registrada.';$('oleoHist').innerHTML='Nenhuma troca registrada.';return}let x=l[0];$('oleoResumo').innerHTML=`<div class="stat"><b>${x.km.toLocaleString('pt-BR')} km</b> — última troca em ${fmtDate(x.data)}<br>Próxima troca: <b>${x.prox.toLocaleString('pt-BR')} km</b> (a cada ${(x.intervalo||x.prox-x.km).toLocaleString('pt-BR')} km)${x.tipo?' • '+x.tipo:''}</div>`;$('oleoHist').innerHTML=l.map((x,i)=>`<div class="item"><b>${fmtDate(x.data)}</b> — ${x.km.toLocaleString('pt-BR')} km<br><span class="small">Próxima: ${x.prox.toLocaleString('pt-BR')} km${x.tipo?' • '+x.tipo:''}${x.valor?' • <b>R$ '+br(x.valor)+'</b>':''}</span><div style="display:flex;gap:7px;margin-top:7px"><button style="width:auto;padding:7px 10px" onclick="editarOleo(${i})">✏️ Editar</button><button class="danger" style="width:auto;padding:7px 10px" onclick="excluirOleo(${i})">🗑️ Excluir</button></div></div>`).join('')}
function salvarMan(){let tipo=$('manTipo').value,motivoPeca='';if(!tipo){alert('Selecione o tipo.');return}if(tipo===TIPO_PECA){let pc=$('manPeca').value.trim();if(!pc){alert('Escolha ou digite qual peça foi trocada.');$('manPeca').focus();return}tipo='Troca de peça: '+pc;motivoPeca=$('manPecaMotivo').value}if(tipo==='Outra manutenção'){tipo=$('manOutro').value.trim();if(!tipo){alert('Digite qual foi a manutenção.');$('manOutro').focus();return}}let x={tipo,data:$('manData').value,km:$('manKm').value?numKm('manKm'):null,proxKm:$('manProxKm').value?numKm('manProxKm'):null,proxData:$('manProxData').value,obs:$('manObs').value.trim(),motivo:motivoPeca,valor:Number($('manValor').value)||0,oficina:$('manOficina').value.trim(),kmDeixei:$('manKmDeixei').value?numKm('manKmDeixei'):null,kmPeguei:$('manKmPeguei').value?numKm('manKmPeguei'):null};if(x.km===null&&x.kmDeixei)x.km=x.kmDeixei;if(x.kmDeixei&&x.kmPeguei&&x.kmPeguei<x.kmDeixei&&!confirm('O KM quando pegou ('+x.kmPeguei.toLocaleString('pt-BR')+') está menor que o KM quando deixou ('+x.kmDeixei.toLocaleString('pt-BR')+'). Salvar mesmo assim?'))return;let l=get('mans',[]),i=localStorage.getItem(K('editMan'));if(i!==null){l[Number(i)]=x;localStorage.removeItem(K('editMan'))}else l.unshift(x);set('mans',l);if(x.kmPeguei)kmDaOficina(x.kmPeguei);limparMan();renderMan();try{renderPainel()}catch(e){}}
function limparMan(){$('manOutroBox').classList.add('hidden');['manTipo','manOutro','manData','manKm','manProxKm','manProxData','manObs','manValor','manOficina','manKmDeixei','manKmPeguei','manPeca','manPecaMotivo'].forEach(x=>$(x).value='');$('manPecaBox').classList.add('hidden');$('manRodou').innerHTML='';$('manIaStatus').textContent='';$('manPrev').innerHTML='';delete $('manProxKm').dataset.auto;delete $('manProxData').dataset.auto;$('manData').value=today();localStorage.removeItem(K('editMan'));modoEdit('Man')}
function editarMan(i){let x=get('mans',[])[i];$('manPeca').value='';$('manPecaMotivo').value='';if(/^Troca de peça: /.test(x.tipo)){$('manTipo').value=TIPO_PECA;$('manPeca').value=x.tipo.slice(15);$('manPecaMotivo').value=x.motivo||'';$('manOutro').value=''}else if([...$('manTipo').options].some(o=>o.value===x.tipo)){$('manTipo').value=x.tipo;$('manOutro').value=''}else{$('manTipo').value='Outra manutenção';$('manOutro').value=x.tipo}trocarTipoMan();$('manData').value=x.data||'';$('manKm').value=x.km||'';$('manProxKm').value=x.proxKm||'';$('manProxData').value=x.proxData||'';$('manObs').value=x.obs||'';$('manValor').value=x.valor||'';$('manOficina').value=x.oficina||'';$('manKmDeixei').value=x.kmDeixei||'';$('manKmPeguei').value=x.kmPeguei||'';formatarKms();calcRodouOf();localStorage.setItem(K('editMan'),i);modoEdit('Man',x.tipo+(x.data?' de '+fmtDate(x.data):''));showTab('man');window.scrollTo({top:0,behavior:'smooth'})}
function rodouOf(d){return d<0?{cor:'bad',t:'⚠️ O KM de quando pegou está menor que o de quando deixou. Confira os números.'}:d<=5?{cor:'ok',t:`✅ Andaram <b>${d} km</b> — normal (só manobra ou teste rápido).`}:d<=15?{cor:'warn',t:`🟡 Andaram <b>${d} km</b> — dá um teste de rua, normal em alguns serviços (freio, embreagem, barulho).`}:{cor:'bad',t:`🔴 Andaram <b>${d.toLocaleString('pt-BR')} km</b> com a sua moto. É bastante — vale perguntar à oficina o porquê.`}}
function calcRodouOf(){let b=$('manRodou');if(!b)return;let a=$('manKmDeixei').value?numKm('manKmDeixei'):0,p=$('manKmPeguei').value?numKm('manKmPeguei'):0;if(!a||!p){b.innerHTML=a?'<span class="small">🔧 Quando pegar a moto, anote o KM (ou salve agora e toque em <b>🏍️ Peguei a moto</b> no histórico).</span>':'';return}let r=rodouOf(p-a);b.innerHTML=`<div class="status ${r.cor}" style="display:block;white-space:normal;text-align:left;padding:8px 10px;font-weight:normal">${r.t}</div>`}
function htmlOficina(x,i){if(!x.oficina&&!x.kmDeixei)return'';let h=`<div class="small" style="margin-top:5px">🏪 ${x.oficina?escH(x.oficina):'Oficina'}${x.kmDeixei?' • deixei com '+x.kmDeixei.toLocaleString('pt-BR')+' km':''}${x.kmPeguei?' • peguei com '+x.kmPeguei.toLocaleString('pt-BR')+' km':''}</div>`;
 if(x.kmDeixei&&x.kmPeguei){let r=rodouOf(x.kmPeguei-x.kmDeixei);h+=`<div class="status ${r.cor}" style="display:block;white-space:normal;text-align:left;margin-top:5px;padding:6px 9px;font-weight:normal">${r.t}</div>`}
 else if(x.kmDeixei)h+=`<div style="margin-top:6px"><span class="status warn">🔧 Moto na oficina</span> <button style="width:auto;padding:7px 10px;margin-top:5px;background:#1f8a4c" onclick="pegueiMoto(${i})">🏍️ Peguei a moto</button></div>`;
 return h}
function kmDaOficina(k){if(k>((get('kmAtual',null)||{}).km||0))set('kmAtual',{km:k,data:today()})}
function pegueiMoto(i){let l=get('mans',[]),x=l[i];if(!x)return;let r=prompt(`Pegou a moto${x.oficina?' na '+x.oficina:''}?\n\nDeixou com ${x.kmDeixei.toLocaleString('pt-BR')} km.\nQual o KM que está marcando no painel agora?`,'');if(r===null)return;let k=Number(String(r).replace(/\D/g,''));if(!k){alert('Digite o KM do painel.');return}
 x.kmPeguei=k;set('mans',l);kmDaOficina(k);renderMan();try{renderPainel()}catch(e){}let d=k-x.kmDeixei;alert(d<0?'O KM digitado é menor que o de quando deixou. Confira em ✏️ Editar.':d<=5?'✅ Andaram '+d+' km — normal.':d<=15?'🟡 Andaram '+d+' km — teste de rua, normal em alguns serviços.':'🔴 Andaram '+d.toLocaleString('pt-BR')+' km com a sua moto. Vale perguntar à oficina o porquê.')}
function excluirMan(i){if(!confirm('Excluir esta manutenção?'))return;let l=get('mans',[]);l.splice(i,1);set('mans',l);renderMan()}
function statusMan(x,ke){let p=[],c='ok';if(x.proxKm){let f=x.proxKm-ke,mg=Math.max(300,Math.round((x.proxKm-(x.km||x.proxKm))*0.1));p.push(f<0?'passou '+Math.abs(f).toLocaleString('pt-BR')+' km':'faltam '+f.toLocaleString('pt-BR')+' km');c=f<0?'bad':f<=mg?'warn':c}if(x.proxData){let d=diasAte(x.proxData);p.push(d<0?'venceu há '+Math.abs(d)+' dias':'faltam '+d+' dias');c=d<0?'bad':d<=30&&c!=='bad'?'warn':c}return p.length?{c,txt:p.join(' • ')}:null}
function bolaMan(x,i,l){if(l.findIndex(y=>y.tipo===x.tipo)!==i)return'';let s=statusMan(x,kmEfetivo());if(!s)return'';return `<div style="margin-top:5px"><span class="status ${s.c}">${s.c==='ok'?'🟢 Em dia':s.c==='warn'?'🟡 Troca chegando':'🔴 Hora de trocar'} — ${s.txt}</span></div>`}
let capEdit=-1;
function capVence(c){let d=new Date(c.compra+'T12:00:00');d.setFullYear(d.getFullYear()+(Number(c.anos)||3));if(c.fab){let f=new Date(c.fab+'-01T12:00:00');f.setFullYear(f.getFullYear()+5);if(f<d)d=f}return d.toISOString().slice(0,10)}
function capStatus(c){if(c.queda)return{c:'bad',txt:'🔴 Trocar — já levou queda/pancada'};let v=capVence(c),d=diasAte(v);if(d<0)return{c:'bad',txt:'🔴 Vencido desde '+fmtDate(v)};if(d<=90)return{c:'warn',txt:'🟡 Trocar em breve — vence em '+fmtDate(v)};let m=Math.round(d/30.4);return{c:'ok',txt:'🟢 Em dia — vale até '+fmtDate(v)+(m>=12?' ('+Math.floor(m/12)+' ano'+(m>=24?'s':'')+(m%12?' e '+(m%12)+' mes'+(m%12>1?'es':''):'')+')':' ('+m+' mes'+(m>1?'es':'')+')')}}
function capPrev(){let b=$('capPrevBox');if(!b)return;let c={compra:$('capCompra').value,fab:$('capFab').value,anos:Number($('capAnos').value)||3,queda:$('capQueda').value==='1'};
 if(!c.compra&&!c.fab){b.innerHTML='';return}if(!c.compra)c.compra=today();let s=capStatus(c),v=capVence(c),pf=c.fab?(()=>{let f=new Date(c.fab+'-01T12:00:00');f.setFullYear(f.getFullYear()+5);return f.toISOString().slice(0,10)})():'';
 let porque=c.queda?'Capacete que levou pancada perde a proteção, mesmo sem marca por fora.':pf&&pf===v?`Conta pela fabricação: 5 anos depois de ${c.fab.split('-').reverse().join('/')}.`:`Conta pela compra: ${c.anos} anos de uso a partir de ${fmtDate(c.compra)}.`;
 b.innerHTML=`<div style="padding:8px 10px;border-radius:10px;background:#fff;border:1px dashed var(--cb)"><span class="status ${s.c}">${s.txt}</span><br><span class="small">${porque}${c.fab?'':' Coloque a fabricação da etiqueta para ficar mais certo.'}</span></div>`}
function abrirCap(i){capEdit=i==null?-1:i;let c=i==null?{quem:'Meu',anos:3}:get('capacetes',[])[i]||{};$('capForm').classList.remove('hidden');$('btnCap').classList.add('hidden');
 $('capQuem').value=c.quem||'Meu';$('capTam').value=c.tam||'';$('capMarca').value=c.marca||'';$('capCompra').value=c.compra||'';$('capFab').value=c.fab||'';$('capAnos').value=String(c.anos||3);$('capValor').value=c.valor||'';$('capQueda').value=c.queda?'1':'';$('capIaStatus').innerHTML='';capPrev()}
