function salvarCap(){let c={quem:$('capQuem').value,tam:$('capTam').value.replace(/\D/g,''),marca:$('capMarca').value.trim(),compra:$('capCompra').value,fab:$('capFab').value,anos:Number($('capAnos').value)||3,valor:Number($('capValor').value)||0,queda:$('capQueda').value==='1'};
 if(!c.compra){alert('Coloque a data da compra do capacete.');return}let l=get('capacetes',[]);if(capEdit>=0&&l[capEdit])l[capEdit]=c;else l.push(c);set('capacetes',l);fecharCap();renderCap();try{renderPainel()}catch(e){}}
function excluirCap(i){let l=get('capacetes',[]);if(!confirm('Excluir este capacete?'))return;l.splice(i,1);set('capacetes',l);renderCap();try{renderPainel()}catch(e){}}
function renderCap(){let box=$('capLista');if(!box)return;let l=get('capacetes',[]);
 box.innerHTML=l.map((c,i)=>{let s=capStatus(c);return `<div class="item"><b>⛑️ ${escH(c.quem)}${c.tam?' • tamanho '+escH(c.tam):''}</b>${c.marca?'<br><span class="small">'+escH(c.marca)+'</span>':''}<br><span class="small">Comprado em ${fmtDate(c.compra)}${c.fab?' • fabricado em '+c.fab.split('-').reverse().join('/'):''}${c.valor?' • <b>R$ '+br(c.valor)+'</b>':''}</span><div style="margin-top:5px"><span class="status ${s.c}">${s.txt}</span></div><div style="display:flex;gap:7px;margin-top:7px"><button style="width:auto;padding:7px 10px" onclick="abrirCap(${i})">✏️ Editar</button><button class="danger" style="width:auto;padding:7px 10px" onclick="excluirCap(${i})">🗑️ Excluir</button></div></div>`}).join('');
 $('btnCap').textContent=l.length?'➕ Adicionar outro capacete':'➕ Adicionar capacete'}
function renderMan(){let l=get('mans',[]);$('manHist').innerHTML=l.length?l.map((x,i)=>`<div class="item"><b>${/^Troca de peça: /.test(x.tipo)?'🧩 ':''}${escH(x.tipo)}</b>${x.motivo?' <span class="small">('+escH(x.motivo)+')</span>':''}${x.data?' — '+fmtDate(x.data):''}<br><span class="small">${x.km!=null?'Feita em '+x.km.toLocaleString('pt-BR')+' km':''}${x.proxKm?' • Próxima: '+x.proxKm.toLocaleString('pt-BR')+' km':''}${x.proxData?' • '+fmtDate(x.proxData):''}${x.obs?' • '+x.obs:''}${x.valor?' • <b>R$ '+br(x.valor)+'</b>':''}</span>${bolaMan(x,i,l)}${htmlOficina(x,i)}<div style="display:flex;gap:7px;margin-top:7px"><button style="width:auto;padding:7px 10px" onclick="editarMan(${i})">✏️ Editar</button><button class="danger" style="width:auto;padding:7px 10px" onclick="excluirMan(${i})">🗑️ Excluir</button>${x.proxData?`<button style="width:auto;padding:7px 10px;background:#1f8a4c" onclick="lembrarMan(${i})">📅 Lembrar</button>`:''}</div></div>`).join(''):'Nenhuma manutenção registrada.'}
$('fuelLitros').addEventListener('input',()=>{calcFuel();dicaNivel()});$('fuelPreco').addEventListener('input',()=>{if(Number($('fuelTotal').value)&&!Number($('fuelLitros').value)||fuelPeloValor)calcLitros();else calcFuel();dicaNivel()});$('fuelTotal').addEventListener('input',()=>{calcLitros();dicaNivel()});$('fuelKm').addEventListener('input',dicaNivel);
let fuelPeloValor=false;function calcFuel(){fuelPeloValor=false;let l=Number($('fuelLitros').value),p=Number($('fuelPreco').value);$('fuelTotal').value=l&&p?(l*p).toFixed(2):''}
function calcLitros(){fuelPeloValor=true;let t=Number($('fuelTotal').value),p=Number($('fuelPreco').value);$('fuelLitros').value=t&&p?(t/p).toFixed(2):''}
function salvarFuel(){let data=$('fuelData').value,km=numKm('fuelKm'),lit=Number($('fuelLitros').value),pre=Number($('fuelPreco').value);if(!data||!km||!lit||!pre){alert('Informe data, KM, preço por litro e os litros (ou o valor pago).');return}let nsel=$('fuelNivel').value,nivel,auto=false;if(nsel==='auto'){auto=true;let e=estimarNivel(km,lit);nivel=e?Math.round(e.frac*100)/100:null}else nivel=Number(nsel);let l=get('fuels',[]),i=localStorage.getItem(K('editFuel')),x={data,km,comb:$('fuelTipo').value,posto:$('fuelPosto').value.trim(),end:$('fuelEnd').value.trim(),lat:fuelPos.lat,lng:fuelPos.lng,litros:lit,preco:pre,total:Number($('fuelTotal').value)||lit*pre,nivel,auto};if(i!==null){l[Number(i)]=x;localStorage.removeItem(K('editFuel'))}else l.unshift(x);l.sort((a,b)=>a.km-b.km);let foiEd=i!==null;set('fuels',l);limparFuel();renderFuel();if(foiEd)alert('Abastecimento atualizado ✅')}
function limparFuel(){fuelPos={lat:null,lng:null};if($('fuelPostoOpc'))$('fuelPostoOpc').innerHTML='';if($('fuelGpsMsg'))$('fuelGpsMsg').textContent='';['fuelData','fuelKm','fuelLitros','fuelPreco','fuelTotal','fuelPosto','fuelEnd'].forEach(x=>$(x).value='');$('fuelData').value=today();$('fuelTipo').value='Gasolina';$('fuelNivel').value='auto';fuelPeloValor=false;localStorage.removeItem(K('editFuel'));modoEdit('Fuel');dicaNivel()}
function fuelCalc(l,i){if(i===0)return null;let A=l[i-1],B=l[i],d=B.km-A.km;if(d<=0)return null;let cap=Number(get('moto',{}).tanque)||0,ok=x=>!x.auto&&x.nivel!=null,lv=x=>x.nivel??1,cheio=x=>ok(x)&&lv(x)===1;
 if(cap&&ok(A)&&ok(B)){let c=lv(A)*cap+B.litros-lv(B)*cap;return c>0.3?d/c:null}
 if(!cheio(B))return null;let j=i-1,lit=B.litros;while(j>=0&&!cheio(l[j])){lit+=l[j].litros;j--}if(j<0)return null;let dd=B.km-l[j].km;return dd>0?dd/lit:null}
function mediaKmL(){let l=get('fuels',[]),v=l.map((x,i)=>fuelCalc(l,i)).filter(Boolean);return v.length?v.reduce((a,b)=>a+b,0)/v.length:0}
const NIVEIS=[[0.25,'¼ tanque'],[0.5,'½ tanque'],[0.75,'¾ tanque'],[1,'tanque cheio']];
function nomeNivel(f){if(f==null)return'nível não informado';let n=NIVEIS.reduce((a,b)=>Math.abs(b[0]-f)<Math.abs(a[0]-f)?b:a);return n[1]}
function estimarNivel(km,litros){let cap=Number(get('moto',{}).tanque)||0;if(!cap||!litros)return null;let l=get('fuels',[]),ed=localStorage.getItem(K('editFuel')),ant=null;
 l.forEach((x,i)=>{if(ed!==null&&i===Number(ed))return;if(km?x.km<km:true){if(!ant||x.km>ant.km)ant=x}});
 let media=mediaKmL(),padrao=!media;if(padrao)media=35;
 let antes,rodou=0;if(ant){let nivAnt=ant.nivel??1;antes=nivAnt*cap;if(km&&km>ant.km){rodou=km-ant.km;antes-=rodou/media}}else antes=cap*0.15;
 antes=Math.max(0,Math.min(cap,antes));let depois=Math.min(cap,antes+litros);return{cap,antes,depois,frac:depois/cap,rodou,media,padrao,transbordou:antes+litros>cap+0.3,semAnterior:!ant}}
function dicaNivel(){let box=$('fuelDica'),auto=$('fuelNivel').value==='auto',lit=Number($('fuelLitros').value),km=numKm('fuelKm'),cap=Number(get('moto',{}).tanque)||0;
 if(!auto){box.innerHTML='';return}
 if(!cap){box.innerHTML='<div class="aviso"><span class="dot">⚠️</span><span>Para o app calcular sozinho, cadastre a <b>capacidade do tanque</b> na aba Moto (✏️ Editar). Até lá, escolha o nível na lista.</span></div>';return}
 if(!lit){box.innerHTML='<p class="small" style="margin:4px 0 0">Digite o KM e os litros que o app mostra como o tanque vai ficar.</p>';return}
 let e=estimarNivel(km,lit),pct=Math.round(e.frac*100);
 box.innerHTML=`<div class="stat" style="text-align:left;margin-top:6px"><span class="small">Pela conta do app:</span><br><b style="font-size:15px">⛽ Vai ficar com ~${br(e.depois,1)} de ${br(e.cap,1)} litros • ${nomeNivel(e.frac)} (${pct}%)</b><div style="height:9px;background:#d5e3ec;border-radius:6px;margin:6px 0;overflow:hidden"><div style="height:100%;width:${pct}%;background:${pct<30?'#d9822b':'#1f8a4c'};border-radius:6px"></div></div><span class="small">Antes de abastecer: ~${br(e.antes,1)} L${e.rodou?' (rodou '+e.rodou.toLocaleString('pt-BR')+' km desde o último)':''}${e.semAnterior?' — 1º abastecimento: considerei o tanque na reserva':''}.${e.padrao?' Usei média de 35 km/L até ter histórico.':' Média da moto: '+br(e.media,1)+' km/L.'}${e.transbordou?' <b>Esses litros enchem o tanque.</b>':''}</span></div>`}
function andou(l,i){if(i===0)return null;let d=l[i].km-l[i-1].km;return d>0?d:null}
function editarFuel(i){let l=get('fuels',[]),x=l[i];$('fuelData').value=x.data;$('fuelKm').value=x.km;$('fuelTipo').value=x.comb;$('fuelPosto').value=x.posto||'';$('fuelEnd').value=x.end||'';fuelPos={lat:x.lat??null,lng:x.lng??null};$('fuelGpsMsg').textContent=x.lat!=null?'📍 Localização já marcada.':'';$('fuelLitros').value=x.litros;$('fuelPreco').value=x.preco;$('fuelNivel').value=x.auto?'auto':String(x.nivel??1);calcFuel();$('fuelTotal').value=x.total?x.total.toFixed(2):$('fuelTotal').value;formatarKms();localStorage.setItem(K('editFuel'),i);modoEdit('Fuel','abastecimento de '+fmtDate(x.data)+' — '+x.km.toLocaleString('pt-BR')+' km');dicaNivel();showTab('fuel');window.scrollTo({top:0,behavior:'smooth'})}
function excluirFuel(i){if(!confirm('Excluir este abastecimento?'))return;let l=get('fuels',[]);l.splice(i,1);set('fuels',l);renderFuel()}
function renderFuel(){let l=get('fuels',[]);if(!l.length){$('fuelResumo').innerHTML='Nenhum abastecimento registrado.';$('fuelHist').innerHTML='Nenhum abastecimento registrado.';return}
let month=today().slice(0,7),idx=l.map((x,i)=>i).filter(i=>l[i].data.slice(0,7)===month),total=idx.reduce((a,i)=>a+l[i].total,0),lit=idx.reduce((a,i)=>a+l[i].litros,0),km=idx.reduce((a,i)=>a+(andou(l,i)||0),0),
valid=l.map((x,i)=>fuelCalc(l,i)).filter(Boolean),avg=valid.length?valid.reduce((a,x)=>a+x,0)/valid.length:0,ult=l[l.length-1],custo=avg?ult.preco/avg:0;
$('fuelResumo').innerHTML=`<div class="kpi"><div><span class="small">Gasto no mês</span><br><b>R$ ${br(total)}</b></div><div><span class="small">Litros no mês</span><br><b>${br(lit)} L</b></div><div><span class="small">Rodou no mês</span><br><b>${km?km.toLocaleString('pt-BR')+' km':'—'}</b></div><div><span class="small">Consumo médio</span><br><b>${avg?br(avg,1)+' km/L':'—'}</b></div><div><span class="small">Custo por km</span><br><b>${custo?'R$ '+br(custo):'—'}</b></div><div><span class="small">Abastecimentos no mês</span><br><b>${idx.length}</b></div></div>${valid.length?'':'<p class="small" style="margin:8px 0 0">O consumo aparece a partir do 2º abastecimento.</p>'}`;

$('fuelHist').innerHTML=l.map((x,i)=>i).reverse().map(i=>{let x=l[i],c=fuelCalc(l,i),a=andou(l,i);return `<div class="item"><b>${fmtDate(x.data)}</b> — ${x.km.toLocaleString('pt-BR')} km${a?` <span class="status ok">andou ${a.toLocaleString('pt-BR')} km</span>`:''}<br>${x.posto?`<span style="font-size:13px">📍 <b>${escH(x.posto)}</b>${x.end?' <span class="small">• '+escH(x.end)+'</span>':''}</span><br>`:''}<span class="small">${x.comb} • ${br(x.litros)} L • R$ ${br(x.preco)}/L • <b>R$ ${br(x.total)}</b> • ${x.auto?'≈ '+nomeNivel(x.nivel)+' <span title="calculado pelo app">🤖</span>':nomeNivel(x.nivel??1)}${c?' • <b>'+br(c,1)+' km/L</b>':''}</span><div style="display:flex;gap:7px;margin-top:7px"><button style="width:auto;padding:7px 10px" onclick="editarFuel(${i})">✏️ Editar</button><button class="danger" style="width:auto;padding:7px 10px" onclick="excluirFuel(${i})">🗑️ Excluir</button>${x.posto||x.end?`<button class="secondary" style="width:auto;padding:7px 10px" onclick="mapaPosto(${i})">🗺️ Mapa</button>`:''}</div></div>`}).join('');renderPostos()}
function salvarDoc(){if(!$('docFinal').value)finalDaPlaca();let d={renavam:$('renavam').value.trim(),placa:$('docPlaca').value.trim().toUpperCase(),venc:$('docVenc').value,final:$('docFinal').value,feito:$('docFeito').value==='1',feitoData:$('docFeito').value==='1'?$('docFeitoData').value:'',feitoValor:$('docFeito').value==='1'?(Number($('docFeitoValor').value)||0):0};if(!d.venc){alert('Informe a data de vencimento.');return}set('doc',d);licDoDoc();renderDoc();renderLic();alert('Documento salvo.'+(d.feito&&d.feitoData?' Licenciamento '+d.feitoData.slice(0,4)+' guardado no histórico.':''))}
function limparDoc(){$('docFeitoBox').classList.add('hidden');['renavam','docPlaca','docVenc','docFinal','docFeito','docFeitoData','docFeitoValor'].forEach(x=>$(x).value='')}
function excluirDoc(){if(!get('doc',null)){alert('Nenhum documento cadastrado.');return}if(confirm('Excluir RENAVAM, placa e vencimento?')){localStorage.removeItem(K('doc'));limparDoc();renderDoc()}}
function renderDoc(){let d=get('doc',null);if(!d){$('docStatus').innerHTML='Cadastre a data de vencimento.';let mp=(get('moto',{}).placa||'');if(mp&&!$('docPlaca').value){$('docPlaca').value=mp;finalDaPlaca()}return} $('renavam').value=d.renavam||'';$('docPlaca').value=d.placa||'';$('docVenc').value=d.venc||'';$('docFeito').value=d.feito?'1':'';$('docFeitoData').value=d.feitoData||'';$('docFeitoValor').value=d.feitoValor||'';$('docFeitoBox').classList.toggle('hidden',!d.feito);$('docFinal').value=d.final??(String(d.placa||'').match(/(\d)\D*$/)||[])[1]??'';let hoje=new Date();hoje.setHours(0,0,0,0),v=new Date(d.venc+'T00:00:00'),dias=Math.ceil((v-hoje)/86400000);let c=dias<0?'bad':dias<=30?'warn':'ok',txt=dias<0?'VENCIDO':dias<=30?'VENCENDO EM BREVE':'EM DIA';$('docStatus').innerHTML=`<div class="stat"><span class="status ${c}">${txt}</span><br><b>${dias<0?'Venceu há '+Math.abs(dias)+' dias.':'Faltam '+dias+' dias.'}</b><br><span class="small">Vencimento: ${fmtDate(d.venc)}${d.renavam?' • RENAVAM: '+d.renavam:''}${d.placa?' • Placa: '+d.placa:''}</span>${d.feito?`<br><span class="status ok" style="margin-top:6px;display:inline-block">✅ Documento feito${d.feitoData?' em '+fmtDate(d.feitoData):''}</span>`:''}</div>${!d.feito&&dias<=60?'<button style="margin-top:10px;background:#1f8a4c" onclick="marcarFeito()">✅ Já fiz o documento</button>':''}`}
async function ativarNotif(){if(!('Notification'in window)){alert('Notificações não suportadas neste navegador.');return}let p=await Notification.requestPermission();if(p==='granted'&&'serviceWorker'in navigator){await navigator.serviceWorker.register('sw.js');alert('Notificações autorizadas. Para avisos automáticos com o app fechado, o próximo passo é ligar o Firebase/Push.')}else alert('Permissão não concedida.')}
async function testarNotif(){if(Notification.permission!=='granted'){alert('Primeiro ative as notificações.');return}let r=await navigator.serviceWorker.ready;r.showNotification('🏍️ Controle da Moto',{body:'Notificação de teste funcionando!',tag:'teste'})}
async function compartilhar(){let u=location.href;if(navigator.share){try{await navigator.share({title:'Controle da Moto',text:'🏍️ Controle da Moto',url:u})}catch(e){}}else{try{await navigator.clipboard.writeText(u);alert('Link copiado.')}catch(e){prompt('Copie o link:',u)}}}

function icsTxt(t){return String(t||'').replace(/\\/g,'\\\\').replace(/[,;]/g,m=>'\\'+m).replace(/\n/g,'\\n')}
function baixarICS(arq,titulo,data,desc){let ini=data.replace(/-/g,''),f=new Date(data+'T12:00:00');f.setDate(f.getDate()+1);let fim=f.toISOString().slice(0,10).replace(/-/g,''),agora=new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z';
let al=(tr,txt)=>['BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+icsTxt(txt),'TRIGGER:'+tr,'END:VALARM'];
let L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Controle da Moto//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT','UID:'+Date.now()+'@controle-moto','DTSTAMP:'+agora,'DTSTART;VALUE=DATE:'+ini,'DTEND;VALUE=DATE:'+fim,'SUMMARY:'+icsTxt(titulo),'DESCRIPTION:'+icsTxt(desc),
...al('-P29DT15H',titulo+' em 30 dias'),...al('-P6DT15H',titulo+' em 7 dias'),...al('-PT15H',titulo+' amanhã'),...al('PT9H',titulo+' hoje'),'END:VEVENT','END:VCALENDAR'];
let ics=L.join('\r\n'),ios=/iP(hone|ad|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
if(ios){location.href='data:text/calendar;charset=utf-8,'+encodeURIComponent(ics);return}
let u=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=arq;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function lembrarDoc(){let d=get('doc',null);if(!d||!d.venc){alert('Salve o documento com a data de vencimento primeiro.');return}let m=get('moto',{});baixarICS('documento-moto.ics','📄 Vence o documento da moto',d.venc,'Controle da Moto'+(d.placa?' • Placa: '+d.placa:'')+(d.renavam?' • RENAVAM: '+d.renavam:'')+(m.modelo?' • '+m.modelo:''))}
function lembrarMan(i){let x=get('mans',[])[i];if(!x||!x.proxData){alert('Esta manutenção não tem próxima data.');return}baixarICS('manutencao-moto.ics','🔧 Moto: '+x.tipo,x.proxData,'Controle da Moto'+(x.proxKm?' • Próxima em '+x.proxKm.toLocaleString('pt-BR')+' km':'')+(x.obs?' • '+x.obs:''))}

let promptInstalar=null;
const ehIOS=/iP(hone|ad|od)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const jaInstalado=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptInstalar=e});
window.addEventListener('appinstalled',()=>{promptInstalar=null;$('btnInstalar').classList.add('hidden');alert('App instalado! Procure o ícone da moto na tela inicial.')});
if(jaInstalado())$('btnInstalar').classList.add('hidden');
function passo(n,t){return `<div class="passo"><span class="num">${n}</span><span>${t}</span></div>`}
async function instalarApp(){
 if(jaInstalado()){alert('O app já está instalado neste celular. 👍');return}
 if(promptInstalar){promptInstalar.prompt();let r=await promptInstalar.userChoice;promptInstalar=null;if(r.outcome!=='accepted')alert('Instalação cancelada. Você pode tentar de novo quando quiser.');return}
 let h;
 if(ehIOS){
  let safari=!/CriOS|FxiOS|EdgiOS|OPiOS/.test(navigator.userAgent);
  h=(safari?'':`<p class="small" style="margin:0 0 8px">Para funcionar melhor, abra este endereço no <b>Safari</b>.</p>`)+passo(1,'Toque no botão <span class="ico">Compartilhar ⬆️</span> (quadrado com a seta para cima, na barra do navegador — se não aparecer, toque em <span class="ico">•••</span>)')+passo(2,'Role e toque em <span class="ico">Adicionar à Tela de Início ➕</span>')+passo(3,'Toque em <span class="ico">Adicionar</span> no canto de cima')+passo(4,'Pronto! O ícone da moto 🏍️ aparece na tela inicial');
 }else{
  h=passo(1,'Toque nos <span class="ico">⋮</span> três pontinhos do Chrome, no canto de cima')+passo(2,'Toque em <span class="ico">Instalar app</span> ou <span class="ico">Adicionar à tela inicial</span>')+passo(3,'Confirme em <span class="ico">Instalar</span>')+passo(4,'Pronto! O ícone da moto 🏍️ aparece na tela inicial');
 }
 $('passosInstalar').innerHTML=h;$('modalInstalar').classList.remove('hidden')}
function fecharInstalar(){$('modalInstalar').classList.add('hidden')}


function mostrarVersao(extra){let vt=$('verTopo');if(vt)vt.textContent='v'+VERSAO;$('versaoInfo').innerHTML='Versão '+VERSAO+' • '+VERSAO_DATA+(extra||'')}
async function atualizarApp(){try{if('caches'in window){let k=await caches.keys();await Promise.all(k.map(x=>caches.delete(x)))}let r=navigator.serviceWorker&&await navigator.serviceWorker.getRegistration();if(r)await r.update()}catch(e){}location.reload()}
async function checarVersao(){mostrarVersao();if(!navigator.onLine){mostrarVersao(' • 📴 sem internet');return}
 try{let t=await(await fetch('index.html?v='+Date.now(),{cache:'no-store'})).text(),m=t.match(/const VERSAO='([^']+)'/);if(!m)return;
 if(m[1]===VERSAO)mostrarVersao(' • ✅ atualizado');
 else mostrarVersao(`<br><button style="margin-top:8px;background:#e08a00" onclick="atualizarApp()">⬆️ Nova versão ${m[1]} disponível — toque para atualizar</button>`)}catch(e){}}

function fmtKm(v){v=String(v??'').replace(/\D/g,'').replace(/^0+(?=\d)/,'');return v?Number(v).toLocaleString('pt-BR'):''}
function numKm(id){return Number(String($(id).value).replace(/\D/g,''))||0}
function formatarKms(){document.querySelectorAll('input.km').forEach(e=>e.value=fmtKm(e.value))}
document.addEventListener('input',e=>{let t=e.target;if(!t.classList||!t.classList.contains('km'))return;let fim=t.value.length-t.selectionStart;t.value=fmtKm(t.value);let pos=Math.max(0,t.value.length-fim);try{t.setSelectionRange(pos,pos)}catch(_){}});
const INTERV_MAN={'Pneu dianteiro':[20000,15000,25000],'Pneu traseiro':[12000,10000,15000],'Kit pneus (dianteiro + traseiro)':[12000,10000,15000,'o traseiro gasta antes do dianteiro'],'Pastilha de freio dianteira':[12000,10000,15000],'Pastilha de freio traseira':[12000,10000,15000],'Kit pastilhas de freio (dianteira + traseira)':[12000,10000,15000,'confira as duas a cada revisão: uma pode gastar antes da outra'],'Corrente':[20000,15000,25000],'Relação (corrente/coroa/pinhão)':[20000,15000,25000],'Correia / transmissão':[24000,18000,25000],'Filtro de ar':[12000,8000,16000],'Vela':[12000,8000,16000],'Revisão geral':[6000,6000,6000,'ou a cada 12 meses, o que vier primeiro'],'Bateria':[0,0,0,'dura uns 2 a 3 anos',24],'Fluido de freio':[0,0,0,'o manual pede a cada 2 anos',24]};
function kmPorDia(){let p=[];get('oleos',[]).forEach(x=>p.push([x.data,x.km]));get('mans',[]).forEach(x=>p.push([x.data,x.km]));get('fuels',[]).forEach(x=>p.push([x.data,x.km]));let ka=get('kmAtual',null);if(ka)p.push([ka.data,ka.km]);
 p=p.filter(x=>x[0]&&x[1]>0).map(x=>[new Date(x[0]+'T12:00:00').getTime(),x[1]]).sort((a,b)=>a[0]-b[0]);if(p.length<2)return 0;let d=(p[p.length-1][0]-p[0][0])/86400000,k=p[p.length-1][1]-p[0][1];return d>=7&&k>0?k/d:0}
function addDias(n){let d=new Date();d.setDate(d.getDate()+Math.round(n));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function mesAno(iso){let m=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'],[y,mm]=iso.split('-');return m[Number(mm)-1]+'/'+y}
function prevMan(){let box=$('manPrev');if(!box)return;let t=$('manTipo').value,r=INTERV_MAN[t],km=$('manKm').value?numKm('manKm'):0,pk=$('manProxKm'),pd=$('manProxData');
 if(!r){box.innerHTML='';return}let [mid,lo,hi,nota,meses]=r,base=$('manData').value||today(),h='';
 if(meses){let d=new Date(base+'T12:00:00');d.setMonth(d.getMonth()+meses);let iso=d.toISOString().slice(0,10);if(!pd.value||pd.dataset.auto){pd.value=iso;pd.dataset.auto=1}
  h=`📈 <b>Próxima troca:</b> por volta de <b>${mesAno(iso)}</b>${nota?' — '+nota:''}.`}
 else if(km){let alvo=km+mid,rate=kmPorDia(),ke=Math.max(kmEfetivo(),km);if(!pk.value||pk.dataset.auto){pk.value=alvo.toLocaleString('pt-BR');pk.dataset.auto=1}
  h=`📈 <b>Próxima troca prevista:</b> por volta dos <b>${alvo.toLocaleString('pt-BR')} km</b>`+(hi>lo?`<br><span class="small">Normalmente entre ${(km+lo).toLocaleString('pt-BR')} e ${(km+hi).toLocaleString('pt-BR')} km — depende do jeito de pilotar, do peso e da cidade${nota?'; '+nota:''}.</span>`:nota?` <span class="small">(${nota})</span>`:'');
  if(rate>0){let dias=(alvo-ke)/rate,iso=addDias(Math.max(0,dias));if(!pd.value||pd.dataset.auto){pd.value=iso;pd.dataset.auto=1}h+=`<br><span class="small">No seu ritmo (~${Math.round(rate)} km por dia), deve chegar lá por <b>${mesAno(iso)}</b>.</span>`}
  else h+='<br><span class="small">Com mais registros de KM, o app também calcula a data.</span>'}
 else h='<span class="small">📈 Coloque o KM em que foi feito para o app prever a próxima troca.</span>';
 box.innerHTML=`<div style="padding:8px 10px;border-radius:10px;background:var(--cl);border:1px dashed var(--cb);font-size:13.5px">${h}<br><span class="small">Estimativa — o app já preencheu "Próxima em KM/data"; pode mudar se o mecânico disser outra coisa.</span></div>`}
document.addEventListener('input',e=>{if(e.target&&(e.target.id==='manProxKm'||e.target.id==='manProxData')&&e.isTrusted)delete e.target.dataset.auto});
const TIPO_PECA='Troca de peça (carenagem, retrovisor...)';
function trocarTipoMan(){try{prevMan()}catch(e){}let pc=$('manTipo').value===TIPO_PECA;$('manPecaBox').classList.toggle('hidden',!pc);if(pc&&!$('manPeca').value)setTimeout(()=>$('manPeca').focus(),50);let o=$('manTipo').value==='Outra manutenção';$('manOutroBox').classList.toggle('hidden',!o);if(o&&!$('manOutro').value)setTimeout(()=>$('manOutro').focus(),50)}
const MES_LIC={1:7,2:7,3:8,4:8,5:9,6:9,7:10,8:10,9:11,0:12};
function preencherVenc(){let f=$('docFinal').value;if(f===''){let v=$('docVenc').value;if(v&&$('docFeito').value==='1'){let fd=$('docFeitoData').value||today();$('docVenc').value=(Number(fd.slice(0,4))+1)+v.slice(4)}return}let m=MES_LIC[f],y=new Date().getFullYear();if($('docFeito').value==='1'){let fd=$('docFeitoData').value;y=(fd?Number(fd.slice(0,4)):y)+1}let d=new Date(y,m,0);$('docVenc').value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function trocarFeito(){let f=$('docFeito').value==='1';$('docFeitoBox').classList.toggle('hidden',!f);if(f&&!$('docFeitoData').value)$('docFeitoData').value=today();preencherVenc()}
function marcarFeito(){$('docFeito').value='1';$('docFeitoData').value=today();trocarFeito();salvarDoc()}
function finalDaPlaca(){let m=$('docPlaca').value.match(/(\d)\D*$/);if(!m)return;if($('docFinal').value!==m[1]){$('docFinal').value=m[1];preencherVenc()}}

