function salvarIPVA(silencio){let old=get('ipva',null)||{},forma=$('ipvaForma').value,nP=forma==='parc'?Number($('ipvaN').value)||null:null,ipn={ano:anoSel(),cc:Number($('ipvaCc').value)||null,venal:Number($('ipvaVenal').value)||null,forma,naoIsento:forma==='isento'?false:!!old.naoIsento,nParc:nP,oficial:Number($('ipvaOficial').value)||null,oficialAno:Number($('ipvaOficial').value)?(old.oficial===Number($('ipvaOficial').value)&&old.oficialAno?old.oficialAno:anoIPVA()):null,oficialData:Number($('ipvaOficial').value)?(old.oficial===Number($('ipvaOficial').value)&&old.oficialData?old.oficialData:today()):null,venc:$('ipvaVenc').value,pago:$('ipvaPago').value==='1',parcPagas:forma==='parc'&&old.forma==='parc'&&old.nParc===nP?(old.parcPagas||{}):{}};if(forma==='parc'){let l=ipvaParcelas(ipn,{base:(ipn.venal||0)*0.02});ipn.pago=!!l&&l.every(x=>ipn.parcPagas[x.i])}set('ipva',ipn);ipvaHistDoAtual();renderIPVA();renderIPVAHist();renderPainel();if(silencio!==true)alert('IPVA '+anoSel()+' salvo.'+(calcIPVA()&&calcIPVA().isento?' Guardado no histórico como isento ✅':''))}
