 let d=get('doc',null);if(d&&d.venc){let n=diasAte(d.venc);a.push([n<0?'bad':n<=30?'warn':'ok',`<b>Documento:</b> ${n<0?'vencido há '+Math.abs(n)+' dias':'vence em '+n+' dias'} (${fmtDate(d.venc)})`])}
 let r=calcIPVA();if(r){if(r.isento)a.push(['ok','<b>IPVA:</b> isento']);else if(r.ip.pago)a.push(['ok','<b>IPVA:</b> pago']);else if(ipvaParcelas(r.ip,r)){let l=ipvaParcelas(r.ip,r),p=ipvaProxima(l);if(p&&p.venc){let n=diasAte(p.venc);a.push([n<0?'bad':n<=7?'warn':'ok',`<b>IPVA ${p.i}ª/${l.length}:</b> ${n<0?'vencida há '+Math.abs(n)+' dias':n===0?'vence hoje':'vence em '+n+' dias'} • R$ ${br(p.valor)}`])}}else if(r.ip.venc){let n=diasAte(r.ip.venc);a.push([n<0?'bad':n<=15?'warn':'ok',`<b>IPVA:</b> ${n<0?'vencido há '+Math.abs(n)+' dias':'vence em '+n+' dias'}${r.pagar?' • R$ '+br(r.pagar):''}`])}}
 let g=get('seguro',null);if(g&&g.venc){let n=diasAte(g.venc);a.push([n<0?'bad':n<=30?'warn':'ok',`<b>Seguro:</b> ${n<0?'vencido há '+Math.abs(n)+' dias':'vence em '+n+' dias'}`])}
 let fa=get('fin',null);if(fa){let pn=finProxima(fa);if(!pn)a.push(['ok',`<b>${fa.tipo}:</b> quitado 🎉`]);else{let n=diasAte(finVenc(fa,pn));a.push([n<0?'bad':n<=5?'warn':'ok',`<b>Parcela ${pn}/${fa.total}:</b> ${n<0?'vencida há '+Math.abs(n)+' dias':n===0?'vence hoje':'vence em '+n+' dias'} • R$ ${br(fa.valor)}`])}}
