 let cs=calibStatus();if(cs)a.push([cs.cor,`<b>Calibragem:</b> ${cs.d===0?'feita hoje':'há '+cs.d+' dia'+(cs.d===1?'':'s')}${cs.cor!=='ok'?' — hora de conferir':''}`]);
 let ipA=get('ipva',null),rA=calcIPVA();if(ipA&&rA&&rA.isento&&get('ipvaHist',[]).length&&!get('ipvaHist',[]).some(x=>x.ano===anoIPVA()))a.push(['warn',`<b>IPVA ${anoIPVA()}:</b> confira se continua isento e salve no histórico (aba Documento)`]);
