const CHAVES_APP=/^(moto|oleos|mans|fuels|doc|oleoIntervalo|kmAtual|ipva|seguro|fipe|lavagens|lavCada|fin|licHist|calib|ipvaHist|trocas|capacetes)(@m\d+)?$|^motosLista$|^motoAtual$/;
async function fazerBackup(){let d={};for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i);if(CHAVES_APP.test(k))d[k]=localStorage.getItem(k)}
 let json=JSON.stringify({app:'controle-moto',versao:VERSAO,data:new Date().toISOString(),dados:d},null,1),nome='backup-moto-'+today()+'.json';
 try{let f=new File([json],nome,{type:'application/json'});if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],title:'Backup Controle da Moto'});return}}catch(e){if(e&&e.name==='AbortError')return}
 let u=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=nome;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function restaurarBackup(inp){let f=inp.files[0];inp.value='';if(!f)return;let r=new FileReader();r.onload=()=>{let b;try{b=JSON.parse(r.result)}catch(e){alert('Arquivo inválido.');return}if(!b||b.app!=='controle-moto'||!b.dados){alert('Este arquivo não é um backup do Controle da Moto.');return}
 if(!confirm('Restaurar o backup de '+new Date(b.data).toLocaleString('pt-BR')+'?\nOs dados atuais deste celular serão substituídos.'))return;
 Object.keys(localStorage).filter(k=>CHAVES_APP.test(k)).forEach(k=>localStorage.removeItem(k));Object.entries(b.dados).forEach(([k,v])=>{if(CHAVES_APP.test(k))localStorage.setItem(k,v)});alert('Backup restaurado! ✅');location.reload()};r.readAsText(f)}
