 let old=get('fin',null)||{},f={tipo:$('finTipo').value,banco:$('finBanco').value.trim(),valor,total,primeira,forma:$('finForma').value,contrato:$('finContrato').value.trim(),chassi:$('finChassi').value.trim().toUpperCase(),entrada:Number($('finEntrada').value)||0,pagas:{},codigo:old.codigo||''};if(old.troca)f.troca=old.troca;
