 t.fechada=today();set('trocas',l);let marcas=[...$('marca').options].map(o=>o.value).filter(Boolean),mod=t.modelo||'',mc=marcas.find(m=>normz(mod).startsWith(normz(m)))||'',ano=(mod.match(/\b(20\d\d)\b/)||[])[1]||'';
