function mapaPosto(i){let x=get('fuels',[])[i];abrirLink('https://www.google.com/maps/search/?api=1&query='+(x.lat!=null?x.lat+','+x.lng:encodeURIComponent(x.end||(x.posto+' Tatuí'))))}
