function montarDobras(){Object.entries(DOBRA).forEach(([t,[txt]])=>{let h=[...document.querySelectorAll('.card h2')].find(x=>x.textContent.includes(txt));if(!h||h.dataset.dobra)return;let card=h.parentElement,body=document.createElement('div');body.id='fb'+t;body.className='fbody';
 while(h.nextSibling)body.appendChild(h.nextSibling);card.appendChild(body);h.dataset.dobra=t;h.classList.add('dobra');let ic=h.textContent.trim().split(' ')[0];h.innerHTML=`<span>${ic} ${txt}</span><span class="seta">+ Novo</span>`;h.onclick=()=>{if(body.classList.contains('aberto')){fecharForm(t);return}abrirForm(t)};fecharForm(t)})}
