function licGravar(ano,data,valor){let h=get('licHist',[]),i=h.findIndex(x=>x.ano===ano);let e={ano,data:data||'',valor:valor||0};if(i>=0){if(!e.valor&&h[i].valor)e.valor=h[i].valor;h[i]=e}else h.push(e);h.sort((a,b)=>b.ano-a.ano);set('licHist',h)}
