 h+=l.map(x=>{let d=x.venc?diasAte(x.venc):null,st=x.paga?`<span class="status ok">✅ paga ${fmtDate(x.paga).slice(0,5)}</span>`:d==null?'<span class="small">sem data</span>':d<0?'<span class="status bad">vencida</span>':x===prox?`<span class="status warn">${d===0?'vence hoje':'em '+d+' dia'+(d===1?'':'s')}</span>`:'<span class="small">a vencer</span>';
  return `<div class="item" style="display:flex;align-items:center;gap:8px;padding:8px 0"><b style="min-width:30px">${x.i}ª</b><span style="flex:1">${x.venc?fmtDate(x.venc):'—'} • <b>R$ ${br(x.valor)}</b></span>${st}<button class="${x.paga?'secondary':''}" style="width:auto;padding:5px 9px;font-size:12px" onclick="${x.paga?'desfazerParcIPVA':'pagarParcIPVA'}(${x.i})">${x.paga?'↩️':'✅'}</button></div>`}).join('');
