function renderCalib(){let box=$('calibInfo');if(!box)return;let x=calibValores(),st=calibStatus(),h='';
 if(!x)h=`<div class="empty" style="text-align:left">${normz(get('moto',{}).modelo||'')?'Não tenho a calibragem desse modelo guardada.':'Cadastre o modelo da moto acima para o app sugerir a calibragem.'} Toque em <b>✏️ Ajustar valores</b> e coloque o que diz o manual (ou a etiqueta na moto).</div>`;
 else{let [ds,ts,dg,tg]=x.v;h=`<table class="gastos"><tr><th></th><th>DIANTEIRO</th><th>TRASEIRO</th></tr><tr><td>🧍 Só o piloto</td><td><b style="font-size:17px">${ds}</b> lb</td><td><b style="font-size:17px">${ts}</b> lb</td></tr><tr><td>👥 Com garupa</td><td><b style="font-size:17px">${dg}</b> lb</td><td><b style="font-size:17px">${tg}</b> lb</td></tr></table>`;
  h+=x.origem==='ref'?`<p class="small" style="margin:8px 0 0">📚 Valor de referência para <b>${x.nome}</b>. Confira no manual ou na etiqueta da moto; se for diferente, toque em ✏️ Ajustar valores.</p>${x.url?`<p class="small" style="margin:4px 0 0">🔗 Fonte: <a href="#" onclick="abrirLink('${x.url}');return false" style="color:var(--c);font-weight:bold">${x.url.replace(/^https:\/\/(www\.)?/,'').split('/')[0]}</a></p>`:''}`:'<p class="small" style="margin:8px 0 0">✔️ Valores que você salvou.</p>'}
 h+='<p class="small" style="margin:4px 0 0">Libras (lb) = PSI. Calibre com os pneus <b>frios</b> (antes de rodar ou depois de 3 horas parada).</p>';
 if(st)h+=`<div style="margin-top:8px"><span class="status ${st.cor}">${st.d===0?'Calibrado hoje':'Última calibragem há '+st.d+' dia'+(st.d===1?'':'s')}</span>${st.cor!=='ok'?' <span class="small">— hora de conferir!</span>':''}</div>`;
 box.innerHTML=h}
function trocarTipoLav(){let casa=$('lavTipo').value==='Lavei em casa',f=$('lavData').closest('.grid');if(f)f.classList.toggle('lavCasa',casa);let lb=$('lavValorLbl');if(lb)lb.textContent=casa?'GASTEI COM PRODUTOS (OPCIONAL)':'VALOR PAGO';$('lavValor').placeholder=casa?'Ex.: shampoo, cera, pretinho — deixe vazio se não comprou nada':'Ex.: 30,00'}
function anoIPVA(){let d=new Date();return d.getMonth()>=11?d.getFullYear()+1:d.getFullYear()}
function avisoIPVAOficial(){let ip=get('ipva',null),r=calcIPVA();if(!ip||(r&&r.isento))return null;let d=new Date(),m=d.getMonth(),dia=d.getDate(),ano=anoIPVA();let janela=(m===11&&dia>=15)||m<=2;if(!janela||(ip.oficial&&ip.oficialAno===ano))return null;return ano}
function naoSouIsento(){let ip=get('ipva',null)||{};ip.naoIsento=true;if(ip.forma==='isento')ip.forma='unica3';set('ipva',ip);renderIPVA();renderPainel()}
function ipvaHistGravar(ano,sit,valor,data){let h=get('ipvaHist',[]),i=h.findIndex(x=>x.ano===ano),e={ano,sit,valor:valor||0,data:data||''};if(i>=0)h[i]=e;else h.push(e);h.sort((a,b)=>b.ano-a.ano);set('ipvaHist',h)}
function ipvaHistDoAtual(){let ip=get('ipva',null),r=calcIPVA();if(!ip||!r)return;let ano=anoSel();
 if(r.isento){ipvaHistGravar(ano,'isento',0,today());return}
 if(ip.pago){let l=ipvaParcelas(ip,r),v=l?l.reduce((s,x)=>s+x.valor,0):(r.pagar||r.base||0),d=l?Object.values(ip.parcPagas||{}).sort().pop():today();let h=get('ipvaHist',[]).find(x=>x.ano===ano);ipvaHistGravar(ano,'pago',v,h&&h.sit==='pago'&&h.data?h.data:d)}}
function guardarIsento(){let ip=get('ipva',null)||{};set('ipva',ip);let an=anoSel();ipvaHistGravar(an,'isento',0,today());renderIPVAHist();renderIPVA();alert('Guardado no histórico: IPVA '+an+' isento ✅')}
function excluirIPVAHist(i){let h=get('ipvaHist',[]);if(!confirm('Excluir o IPVA '+h[i].ano+' do histórico?'))return;h.splice(i,1);set('ipvaHist',h);renderIPVAHist()}
function abrirIPVAHistForm(){let b=$('ipvaHForm');b.classList.toggle('hidden');if(!b.classList.contains('hidden')){$('ipvaHAno').value=new Date().getFullYear()-1;$('ipvaHSit').value='isento';$('ipvaHValor').value='';$('ipvaHData').value=''}}
function salvarIPVAHist(){let ano=Number($('ipvaHAno').value);if(!ano||ano<1980||ano>2100){alert('Informe o ano. Ex.: 2025');return}ipvaHistGravar(ano,$('ipvaHSit').value,Number($('ipvaHValor').value)||0,$('ipvaHData').value);$('ipvaHForm').classList.add('hidden');renderIPVAHist()}
function renderIPVAHist(){try{montarAnosIPVA()}catch(e){}let box=$('ipvaHist');if(!box)return;let h=get('ipvaHist',[]);
 box.innerHTML=h.length?h.map((x,i)=>`<div class="item" style="display:flex;align-items:center;gap:8px"><b style="font-size:16px;min-width:44px">${x.ano}</b><span style="flex:1">${x.sit==='isento'?'✅ <b>Isento</b>':'✅ Pago'+(x.valor?' • <b>R$ '+br(x.valor)+'</b>':'')}${x.data&&x.sit!=='isento'?' <span class="small">em '+fmtDate(x.data)+'</span>':''}</span><button class="danger" style="width:auto;padding:5px 9px;font-size:12px" onclick="excluirIPVAHist(${i})">🗑️</button></div>`).join(''):'<div class="empty">Nada no histórico ainda. Quando você salvar o IPVA como <b>isento</b> ou <b>pago</b>, o ano entra aqui sozinho.</div>'}
function ccIPVAMudou(){let cc=Number($('ipvaCc').value)||0;if(cc>=49&&cc<=180&&$('ipvaForma').value!=='isento'){let ip=get('ipva',null)||{};if(ip.naoIsento)return;$('ipvaForma').value='isento';trocarFormaIPVA();salvarIPVA(true)}else if(cc>180&&$('ipvaForma').value==='isento'){$('ipvaForma').value='unica3';trocarFormaIPVA();salvarIPVA(true)}}
function ajustarIsentoAuto(){let ip=get('ipva',null),cc=(ip&&ip.cc)||ccDoModelo();if(!ip||ip.naoIsento||ip.forma==='isento'||!cc||cc>180)return;ip.forma='isento';if(!ip.cc)ip.cc=cc;set('ipva',ip);ipvaHistDoAtual()}
function anoSel(){let v=$('ipvaAno')&&Number($('ipvaAno').value);return v||((get('ipva',null)||{}).ano)||anoIPVA()}
function montarAnosIPVA(){let sel=$('ipvaAno');if(!sel)return;let a=anoIPVA(),atual=Number(sel.value)||0,ops=[];for(let y=a+1;y>=a-6;y--)ops.push(y);sel.innerHTML=ops.map(y=>`<option value="${y}">${y}${y===a?' (atual)':''}${get('ipvaHist',[]).some(x=>x.ano===y)?' ✅ salvo':''}</option>`).join('');sel.value=String(atual&&ops.includes(atual)?atual:a)}
function trocarAnoIPVA(){renderIPVA()}
function render(){try{ajustarIsentoAuto()}catch(e){console.error(e)}try{renderIPVAHist()}catch(e){console.error(e)}try{renderCalib()}catch(e){console.error(e)}try{licDoDoc();renderLic()}catch(e){console.error(e)}try{dicaNivel()}catch(e){}renderMotoBar();renderFin();try{renderTroca()}catch(e){console.error(e)}try{renderCap()}catch(e){console.error(e)}renderLav();renderMotoResumo();renderIPVA();renderSeguro();carregarMoto();renderOleo();renderMan();renderFuel();renderDoc()}
['renderOleo','renderMan','renderFuel','renderDoc','renderLav','renderFin'].forEach(n=>{const f=window[n];window[n]=function(){const r=f.apply(this,arguments);try{renderPainel()}catch(e){console.error(e)}return r}});
ligarDobras();['editFuel','editOleo','editMan','editLav'].forEach(k=>localStorage.removeItem(K(k)));$('lavData').value=today();$('oleoData').value=today();$('oleoIntervalo').value=localStorage.getItem(K('oleoIntervalo'))||'';formatarKms();$('manData').value=today();$('fuelData').value=today();render();checarVersao();
if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{})}
const TEMAS={azul:{n:'Azul',c:'#176b91',cd:'#123b5d',c0:'#071622',cl:'#eaf3f8',cb:'#cfe1ec'},marinho:{n:'Marinho',c:'#1f4e8c',cd:'#163a69',c0:'#0a1730',cl:'#e9eff8',cb:'#c9d7ec'},verde:{n:'Verde',c:'#1f8a4c',cd:'#17603a',c0:'#06210f',cl:'#e7f4ec',cb:'#c4e3cf'},turquesa:{n:'Turquesa',c:'#11808a',cd:'#0d5c63',c0:'#041d20',cl:'#e4f3f4',cb:'#bfe1e4'},roxo:{n:'Roxo',c:'#6b4fa0',cd:'#4b3672',c0:'#1a1030',cl:'#f0ebf8',cb:'#d9cdee'},rosa:{n:'Rosa',c:'#c2477e',cd:'#8c2f59',c0:'#2e0b1b',cl:'#fbeaf2',cb:'#f0c8da'},vermelho:{n:'Vinho',c:'#a8323e',cd:'#7a232d',c0:'#260a0d',cl:'#f8e9eb',cb:'#ecc6ca'},laranja:{n:'Laranja',c:'#c8601a',cd:'#8f4310',c0:'#2b1203',cl:'#fcefe5',cb:'#f1d0b8'},grafite:{n:'Grafite',c:'#4a5560',cd:'#2f363d',c0:'#0f1214',cl:'#eef0f2',cb:'#d3d8dd'},preto:{n:'Preto',c:'#1d1f22',cd:'#1d1f22',c0:'#000000',cl:'#eeeeee',cb:'#d0d0d0'},marrom:{n:'Marrom',c:'#7a5233',cd:'#573a24',c0:'#1f140c',cl:'#f4eee9',cb:'#e2d3c6'},dourado:{n:'Dourado',c:'#a87b12',cd:'#76560c',c0:'#251a03',cl:'#f8f1e1',cb:'#ead9b0'}};
function aplicarTema(k){let t=TEMAS[k]||TEMAS.azul,r=document.documentElement.style;['c','cd','c0','cl','cb'].forEach(v=>r.setProperty('--'+v,t[v]));let m=document.querySelector('meta[name=theme-color]');if(m)m.content=t.cd;try{localStorage.setItem('tema',TEMAS[k]?k:'azul')}catch(e){}let l=document.getElementById('temaLista');if(l)l.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.k===k))}
function abrirTemas(){let atual=localStorage.getItem('tema')||'azul';$('temaLista').innerHTML=Object.entries(TEMAS).map(([k,t])=>`<button data-k="${k}" class="${k===atual?'on':''}" onclick="aplicarTema('${k}')"><i style="background:${t.c}"></i>${t.n}</button>`).join('');$('modalTema').classList.remove('hidden')}
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('.status'))$('modalLeg').classList.remove('hidden')});
try{aplicarTema(localStorage.getItem('tema')||'azul')}catch(e){}
/* 💲 Campos de dinheiro: mostram 65,00 / 1.234,50 e o resto do app continua lendo o número normal */
(function(){const D=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
 const casas=el=>{let s=String(el.getAttribute('data-casas')||el.getAttribute('step')||'0.01');return s.includes('.')?s.split('.')[1].length:2};
 const parse=t=>{t=String(t??'').trim().replace(/[^\d,.-]/g,'');if(!t)return'';if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');else if(/^\d+\.\d{1,3}$/.test(t)&&!/^\d{1,3}\.\d{3}$/.test(t))t=t;else t=t.replace(/\./g,'');let n=Number(t);return isFinite(n)?String(n):''};
 const fmt=(v,c)=>{if(v===''||v==null)return'';let n=Number(v);if(!isFinite(n))return'';return n.toLocaleString('pt-BR',{minimumFractionDigits:Math.min(c,2),maximumFractionDigits:c})};
 function liga(el){if(el.dataset.money)return;el.dataset.money=1;let c=casas(el);el.type='text';el.setAttribute('inputmode','decimal');el.setAttribute('autocomplete','off');
  Object.defineProperty(el,'value',{configurable:true,get(){return parse(D.get.call(el))},set(v){let s=String(v??'');D.set.call(el,s===''?'':fmt(/,/.test(s)?parse(s):s,c))}});
  el.addEventListener('blur',()=>{let p=parse(D.get.call(el));D.set.call(el,p===''?'':fmt(p,c))});
  let raw=D.get.call(el);if(raw)el.value=raw}
 window.ligarDinheiro=()=>document.querySelectorAll('.pre input').forEach(liga);
 try{ligarDinheiro()}catch(e){console.error(e)}})();
